sql:
SELECT [Anomalies Sigma 1 Regions Cruise].Year AS Expr1, Avg([Anomalies Sigma 1 Regions Cruise].Date) AS Date, Avg([Anomalies Sigma 1 Regions Cruise].Month) AS Month, Count([Anomalies Sigma 1 Regions Cruise].NoStations) AS NoCruises, Avg([Anomalies Sigma 1 Regions Cruise].Sigma) AS AvgOfSigma, Avg([Anomalies Sigma 1 Regions Cruise].Depth) AS Depth, Avg([Anomalies Sigma 1 Regions Cruise].Temp) AS Temp, Avg([Anomalies Sigma 1 Regions Cruise].Sal) AS Sal, Avg([Anomalies Sigma 1 Regions Cruise].PO4) AS PO4, Avg([Anomalies Sigma 1 Regions Cruise].SiO4) AS SiO4, Avg([Anomalies Sigma 1 Regions Cruise].NO3) AS NO3, Avg([Anomalies Sigma 1 Regions Cruise].O2) AS O2, Avg([Anomalies Sigma 1 Regions Cruise].O2Sat) AS O2Sat, Avg([Anomalies Sigma 1 Regions Cruise].DepthAnom) AS DepthAnom, Avg([Anomalies Sigma 1 Regions Cruise].TempAnom) AS TempAnom, Avg([Anomalies Sigma 1 Regions Cruise].SalAnom) AS SalAnom, Avg([Anomalies Sigma 1 Regions Cruise].NO3Anom) AS NO3Anom, Avg([Anomalies Sigma 1 Regions Cruise].PO4Anom) AS PO4Anom, Avg([Anomalies Sigma 1 Regions Cruise].SiO3Anom) AS SiO3Anom, Avg([Anomalies Sigma 1 Regions Cruise].O2Anom) AS O2Anom, Avg([Anomalies Sigma 1 Regions Cruise].[N-P_Ratio]) AS [N-P_Ratio], Avg([Anomalies Sigma 1 Regions Cruise].[N-Star]) AS [N-Star]
FROM [Anomalies Sigma 1 Regions Cruise]
GROUP BY [Anomalies Sigma 1 Regions Cruise].Year;

UPDATE Cast INNER JOIN Prodo_Cast ON Cast.Cst_Cnt = Prodo_Cast.Cst_Cnt
SET Prodo_Cast.Cast_ID = [cast].[cast_ID]
WHERE (((Cast.cast_ID)<>[prodo_cast].[cast_ID]));

SELECT Bottle.Cst_Cnt, Bottle.Btl_Cnt, Cast.Cruise, Cast.Cruz_Sta, Cast.DbSta_ID, Cast.Cast_ID, Cast.Sta_ID, Cast.Sta_Code, Bottle.Depth_ID, Bottle.Depthm, Bottle.T_degC, Bottle_Q.T_prec, Bottle_Q.T_qual, Bottle.Salnty, Bottle_Q.S_prec, Bottle_Q.S_qual, Bottle_Q.P_qual, Bottle.O2ml_L, Bottle_Q.O_qual, Nuts.PO4uM, Nuts.PO4q, Nuts.SiO3uM, Nuts.SiO3qu, Nuts.NO2uM, Nuts.NO2q, Nuts.NO3uM, Nuts.NO3q, Nuts.NH3uM, Nuts.NH3q, Chl.ChlorA, Chl.Chlqua, Chl.Phaeop, Chl.Phaqua, Bottle.STheta, Bottle_Q.SThtaq, Bottle.O2Sat, Bottle_Q.O2Satq, Bottle.BtlNum, Prodo_Bottle.C14As1, Prodo_Bottle.C14A1p, Prodo_Bottle.C14A1q, Prodo_Bottle.C14As2, Prodo_Bottle.C14A2p, Prodo_Bottle.C14A2q, Prodo_Bottle.DarkAs, Prodo_Bottle.DarkAp, Prodo_Bottle.DarkAq, Prodo_Bottle.MeanAs, Prodo_Bottle.MeanAp, Prodo_Bottle.MeanAq, Prodo_Bottle.IncTim, Prodo_Bottle.LightP, Bottle.RecInd, Rpt_Data.R_Depth, Rpt_Data.R_TEMP, Rpt_Data.R_POTEMP, Rpt_Data.R_SALINITY, Rpt_Data.R_SIGMA, Rpt_Data.R_SVA, Rpt_Data.R_DYNHT, Rpt_Data.R_O2, Rpt_Data.R_O2Sat, Rpt_Data.R_SIO3, Rpt_Data.R_PO4, Rpt_Data.R_NO3, Rpt_Data.R_NO2, Rpt_Data.R_NH4, Rpt_Data.R_CHLA, Rpt_Data.R_PHAEO, Rpt_Data.R_PRES, Rpt_Data.R_SAMP INTO 0501Bottle2013
FROM ((Bottle INNER JOIN ((Bottle_Q INNER JOIN (Cast INNER JOIN Prodo_Bottle ON Cast.Cst_Cnt = Prodo_Bottle.Cst_Cnt) ON Bottle_Q.Btl_Cnt = Prodo_Bottle.Btl_Cnt) INNER JOIN Rpt_Data ON Prodo_Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) ON Bottle.Btl_Cnt = Bottle_Q.Btl_Cnt) INNER JOIN Chl ON Bottle.Btl_Cnt = Chl.Btl_Cnt) INNER JOIN Nuts ON (Cast.Cst_Cnt = Bottle.Cst_Cnt) AND (Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) AND (Bottle.Btl_Cnt = Prodo_Bottle.Btl_Cnt) AND (Bottle.Btl_Cnt = Nuts.Btl_Cnt)
WHERE (((Cast.Cruise)=200501));

SELECT [Depth Data - 1 Stations].Year, [Depth Data - 1 Stations].Cruise, Avg([Depth Data - 1 Stations].Date) AS Date, Avg([Depth Data - 1 Stations].Month) AS Month, Count([Depth Data - 1 Stations].Depth) AS St_Count, Avg([Depth Data - 1 Stations].Depth) AS Depth, Avg([Depth Data - 1 Stations].Temp) AS Temp, Avg([Depth Data - 1 Stations].Sal) AS Sal, Avg([Depth Data - 1 Stations].Density) AS Density, Avg([Depth Data - 1 Stations].Chl) AS Chl, Avg([Depth Data - 1 Stations].PO4) AS PO4, Avg([Depth Data - 1 Stations].SiO4) AS SiO4, Avg([Depth Data - 1 Stations].NO2) AS NO2, Avg([Depth Data - 1 Stations].NO3) AS NO3, Avg([Depth Data - 1 Stations].O2) AS O2
FROM [Depth Data - 1 Stations]
GROUP BY [Depth Data - 1 Stations].Year, [Depth Data - 1 Stations].Cruise;

SELECT [Depth Data - 2 Cruises].Year, Avg([Depth Data - 2 Cruises].Depth) AS Depth, Avg([Depth Data - 2 Cruises].Temp) AS Temp, Avg([Depth Data - 2 Cruises].Sal) AS Sal, Avg([Depth Data - 2 Cruises].Density) AS Density, Avg([Depth Data - 2 Cruises].Chl) AS Chl, Avg([Depth Data - 2 Cruises].PO4) AS PO4, Avg([Depth Data - 2 Cruises].SiO4) AS SiO4, Avg([Depth Data - 2 Cruises].NO2) AS NO2, Avg([Depth Data - 2 Cruises].NO3) AS NO3, Avg([Depth Data - 2 Cruises].O2) AS O2
FROM [Depth Data - 2 Cruises]
GROUP BY [Depth Data - 2 Cruises].Year;

SELECT Bottle_All.Cst_Cnt, Bottle_All.Btl_Cnt, Bottle_All.Sta_ID, Bottle_All.Depth_ID, Bottle_All.Depthm, Bottle_All.T_degC, Bottle_All.Salnty, Bottle_All.O2ml_L, Bottle_All.STheta, Bottle_All.O2Sat, Bottle_All.[Oxy_µmol/Kg], Bottle_All.BtlNum, Bottle_All.RecInd, Bottle_All.T_prec, Bottle_All.T_qual, Bottle_All.S_prec, Bottle_All.S_qual, Bottle_All.P_qual, Bottle_All.O_qual, Bottle_All.SThtaq, Bottle_All.O2Satq, Bottle_All.ChlorA, Bottle_All.Chlqua, Bottle_All.Phaeop, Bottle_All.Phaqua, Bottle_All.PO4ug, Bottle_All.PO4q, Bottle_All.SiO3ug, Bottle_All.SiO3qu, Bottle_All.NO2ug, Bottle_All.NO2q, Bottle_All.NO3ug, Bottle_All.NO3q, Bottle_All.NH3ug, Bottle_All.NH3q, Bottle_All.C14As1, Bottle_All.C14A1p, Bottle_All.C14A1q, Bottle_All.C14As2, Bottle_All.C14A2p, Bottle_All.C14A2q, Bottle_All.DarkAs, Bottle_All.DarkAp, Bottle_All.DarkAq, Bottle_All.MeanAs, Bottle_All.MeanAp, Bottle_All.MeanAq, Bottle_All.IncTim, Bottle_All.LightP, Bottle_All.R_Depth, Bottle_All.R_TEMP, Bottle_All.R_POTEMP, Bottle_All.R_SALINITY, Bottle_All.R_SIGMA, Bottle_All.R_SVA, Bottle_All.R_DYNHT, Bottle_All.R_O2, Bottle_All.R_O2Sat, Bottle_All.R_SIO3, Bottle_All.R_PO4, Bottle_All.R_NO3, Bottle_All.R_NO2, Bottle_All.R_NH4, Bottle_All.R_CHLA, Bottle_All.R_PHAEO, Bottle_All.R_PRES, Bottle_All.R_SAMP, Bottle_All.[R_Oxy_µmol/Kg], Bottle_All.DIC1, Bottle_All.DIC2, Bottle_All.TA1, Bottle_All.TA2, Bottle_All.[DIC Quality Comment]
FROM Bottle_All
ORDER BY Bottle_All.Btl_Cnt;

SELECT Cast_All.Cst_Cnt AS Expr1, Cast_All.Cruise_ID AS Expr2, Cast_All.Cruz_Sta AS Expr3, Cast_All.DbSta_ID AS Expr4, Cast_All.Cast_ID AS Expr5, Cast_All.Sta_ID AS Expr6, Cast_All.Quarter AS Expr7, Cast_All.Sta_Code AS Expr8, Cast_All.Distance AS Expr9, Format([Cast].[Date],"mm/dd/yyyy") AS Date, Cast_All.Year AS Expr10, Cast_All.Month AS Expr11, Cast_All.Julian_Date AS Expr12, Cast_All.Julian_Day AS Expr13, Cast_All.Time AS Expr14, Cast_All.Lat_Dec AS Expr15, Cast_All.Lat_Deg AS Expr16, Cast_All.Lat_Min AS Expr17, Cast_All.Lat_Hem AS Expr18, Cast_All.Lon_Dec AS Expr19, Cast_All.Lon_Deg AS Expr20, Cast_All.Lon_Min AS Expr21, Cast_All.Lon_Hem AS Expr22, Cast_All.Rpt_Line AS Expr23, Cast_All.St_Line AS Expr24, Cast_All.Ac_Line AS Expr25, Cast_All.Rpt_Sta AS Expr26, Cast_All.St_Station AS Expr27, Cast_All.Ac_Sta AS Expr28, Cast_All.Bottom_D AS Expr29, Cast_All.Ship_Name AS Expr30, Cast_All.Ship_Code AS Expr31, Cast_All.Data_Type AS Expr32, Cast_All.Order_Occ AS Expr33, Cast_All.Event_Num AS Expr34, Cast_All.Cruz_Leg AS Expr35, Cast_All.Orig_Sta_ID AS Expr36, Cast_All.Data_Or AS Expr37, Cast_All.Cruz_Num AS Expr38, Cast_All.IntChl AS Expr39, Cast_All.IntC14 AS Expr2, Cast_All.Inc_Str AS Expr40, Cast_All.Inc_End AS Expr41, Cast_All.PST_LAN AS Expr42, Cast_All.Civil_T AS Expr43, Cast_All.TimeZone AS Expr44, Cast_All.Wave_Dir AS Expr45, Cast_All.Wave_Ht AS Expr46, Cast_All.Wave_Prd AS Expr47, Cast_All.Wind_Dir AS Expr48, Cast_All.Wind_Spd AS Expr49, Cast_All.Barometer AS Expr50, Cast_All.Dry_T AS Expr51, Cast_All.Wet_T AS Expr52, Cast_All.Wea AS Expr53, Cast_All.Cloud_Typ AS Expr54, Cast_All.Cloud_Amt AS Expr55, Cast_All.Visibility AS Expr56, Cast_All.Secchi AS Expr3, Cast_All.ForelU AS Expr4
FROM Cast_All
ORDER BY Cast_All.Cst_Cnt;

SELECT [Isopycnal Properties - 1 Station].Year, Avg([Isopycnal Properties - 1 Station].YearValue) AS AvgOfYearValue, [Isopycnal Properties - 1 Station].Cruise, Avg([Isopycnal Properties - 1 Station].Date) AS Date, Avg([Isopycnal Properties - 1 Station].Month) AS Month, Sum([Isopycnal Properties - 1 Station].StCount) AS NoStations, Avg([Isopycnal Properties - 1 Station].STheta) AS STheta, Avg([Isopycnal Properties - 1 Station].Depth) AS Depth, Avg([Isopycnal Properties - 1 Station].Temp) AS Temp, Avg([Isopycnal Properties - 1 Station].Sal) AS Sal, Avg([Isopycnal Properties - 1 Station].PO4) AS PO4, Avg([Isopycnal Properties - 1 Station].SiO4) AS SiO4, Avg([Isopycnal Properties - 1 Station].NO2) AS NO2, Avg([Isopycnal Properties - 1 Station].NO3) AS NO3, Avg([Isopycnal Properties - 1 Station].O2) AS O2, Avg([Isopycnal Properties - 1 Station].O2Sat) AS O2Sat, Avg([Isopycnal Properties - 1 Station].[N-P_Ratio]) AS [N-P_Ratio], Avg([Isopycnal Properties - 1 Station].[N-Star]) AS [N-Star]
FROM [Isopycnal Properties - 1 Station]
GROUP BY [Isopycnal Properties - 1 Station].Year, [Isopycnal Properties - 1 Station].Cruise;

SELECT [Isopycnal Properties - 2 Cruises].Year, Avg([Isopycnal Properties - 2 Cruises].Date) AS AvgDate, Avg([Isopycnal Properties - 2 Cruises].Month) AS AvgMonth, Count([Isopycnal Properties - 2 Cruises].NoStations) AS CruiseCount, Avg([Isopycnal Properties - 2 Cruises].STheta) AS STheta, Avg([Isopycnal Properties - 2 Cruises].Depth) AS Depth, Avg([Isopycnal Properties - 2 Cruises].Temp) AS Temp, Avg([Isopycnal Properties - 2 Cruises].Sal) AS Sal, Avg([Isopycnal Properties - 2 Cruises].PO4) AS PO4, Avg([Isopycnal Properties - 2 Cruises].SiO4) AS SiO4, Avg([Isopycnal Properties - 2 Cruises].NO2) AS NO2, Avg([Isopycnal Properties - 2 Cruises].NO3) AS NO3, Avg([Isopycnal Properties - 2 Cruises].O2) AS O2, Avg([Isopycnal Properties - 2 Cruises].O2Sat) AS O2Sat
FROM [Isopycnal Properties - 2 Cruises]
GROUP BY [Isopycnal Properties - 2 Cruises].Year;

SELECT [ML Data 1 Stations].Year, [ML Data 1 Stations].Cruise, Avg([ML Data 1 Stations].Date) AS Date, Avg([ML Data 1 Stations].Month) AS Month, Count([ML Data 1 Stations].SampleCount) AS StationCount, Avg([ML Data 1 Stations].Temp) AS Temp, Avg([ML Data 1 Stations].Sal) AS Sal, Avg([ML Data 1 Stations].Density) AS Density, Avg([ML Data 1 Stations].Chl) AS Chl, Avg([ML Data 1 Stations].IntChl) AS IntChl, Avg([ML Data 1 Stations].IntC14) AS IntC14, Avg([ML Data 1 Stations].PO4) AS PO4, Avg([ML Data 1 Stations].SiO4) AS SiO4, Avg([ML Data 1 Stations].NO2) AS NO2, Avg([ML Data 1 Stations].NO3) AS NO3, Avg([ML Data 1 Stations].MLD_Sigma) AS MLD, Avg([ML Data 1 Stations].NCDepth) AS NCDepth, Avg([ML Data 1 Stations].O2) AS O2, Avg([ML Data 1 Stations].O2Sat) AS O2_Sat
FROM [ML Data 1 Stations]
GROUP BY [ML Data 1 Stations].Year, [ML Data 1 Stations].Cruise;

SELECT [ML Data 2 Cruises].Year, Avg([ML Data 2 Cruises].Date) AS Date, Avg([ML Data 2 Cruises].Month) AS Month, Count([ML Data 2 Cruises].StationCount) AS CruiseCount, Avg([ML Data 2 Cruises].Temp) AS Temp, Avg([ML Data 2 Cruises].Sal) AS Sal, Avg([ML Data 2 Cruises].Density) AS Density, Avg([ML Data 2 Cruises].Chl) AS Chl, Avg([ML Data 2 Cruises].IntChl) AS IntChl, Avg([ML Data 2 Cruises].IntC14) AS IntC14, Avg([ML Data 2 Cruises].PO4) AS PO4, Avg([ML Data 2 Cruises].SiO4) AS SiO4, Avg([ML Data 2 Cruises].NO2) AS NO2, Avg([ML Data 2 Cruises].NO3) AS NO3, Avg([ML Data 2 Cruises].MLD) AS MLD, Avg([ML Data 2 Cruises].NCDepth) AS NCDepth, Avg([ML Data 2 Cruises].O2) AS O2, Avg([ML Data 2 Cruises].O2_Sat) AS O2_Sat
FROM [ML Data 2 Cruises]
GROUP BY [ML Data 2 Cruises].Year;

SELECT Cast.Cast_ID, NutClineDepth.NCDepth AS Expr1 INTO [MLD_Nutricline new]
FROM Cast INNER JOIN NutClineDepth ON Cast.Cast_ID = NutClineDepth.Cast_ID
GROUP BY Cast.Cast_ID, NutClineDepth.NCDepth;

SELECT Cast_All.DbSta_ID, Bottle_All.* INTO Bottle_113sta
FROM Cast_All INNER JOIN Bottle_All ON Cast_All.Cst_Cnt=Bottle_All.Cst_Cnt
WHERE (((Cast_All.St_Line)<94 And (Cast_All.St_Line)>59.5) AND ((Cast_All.St_Station)<130));

SELECT Cast_All.* INTO Cast_113Sta
FROM Cast_All
WHERE (((Cast_All.St_Line)<94 And (Cast_All.St_Line)>59.5) AND ((Cast_All.St_Station)<130));

SELECT Bottle.*, Bottle_Q.*, Chl.*, Nuts.*, Prodo_Bottle.*, Rpt_Data.R_PRES, Rpt_Data.R_POTEMP, Rpt_Data.R_SVA, Rpt_Data.R_DYNHT, Rpt_Data.R_NH4, Rpt_Data.[R_Oxy_µmol/Kg], DICs.DIC1, DICs.DIC2, DICs.TA1, DICs.TA2, DICs.pH1, DICs.pH2, DICs.Btl_Cnt, DICs.[DIC Quality Comment] INTO Bottle_All_2105
FROM Cast INNER JOIN ((((((Bottle LEFT JOIN DICs ON Bottle.Btl_Cnt = DICs.Btl_Cnt) INNER JOIN Bottle_Q ON Bottle.Btl_Cnt = Bottle_Q.Btl_Cnt) INNER JOIN Chl ON Bottle.Btl_Cnt = Chl.Btl_Cnt) INNER JOIN Nuts ON Bottle.Btl_Cnt = Nuts.Btl_Cnt) INNER JOIN Prodo_Bottle ON Bottle.Btl_Cnt = Prodo_Bottle.Btl_Cnt) INNER JOIN Rpt_Data ON Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((Cast.Cruise)<=202105));

SELECT Cast.Cst_Cnt, Cast.Cruise_ID, Cast.Cruise, Cast.Cruz_Sta, Cast.DbSta_ID, Cast.Cast_ID, Cast.Sta_ID, Cast.Quarter, Cast.Sta_Code, Cast.Distance, Format([Cast].[Date],"mm/dd/yyyy") AS Date, Cast.Year, Cast.Month, Cast.Julian_Date, Cast.Julian_Day, Format([Cast].[Time],"hh:nn:ss") AS Time, Cast.Lat_Dec, Cast.Lat_Deg, Cast.Lat_Min, Cast.Lat_Hem, Cast.Lon_Dec, Cast.Lon_Deg, Cast.Lon_Min, Cast.Lon_Hem, Cast.Rpt_Line, Cast.St_Line, Cast.Ac_Line, Cast.Rpt_Sta, Cast.St_Station, Cast.Ac_Sta, Cast.Bottom_D, Cast.Secchi, Cast.ForelU, Cast.Ship_Name, Cast.Ship_Code, Cast.Data_Type, Cast.Order_Occ, Cast.Event_Num, Cast.Cruz_Leg, Cast.Orig_Sta_ID, Cast.Data_Or, Cast.Cruz_Num, Cast.IntChl, Cast.IntC14, Prodo_Cast.*, Weather.* INTO Cast_2105
FROM (Cast INNER JOIN Prodo_Cast ON Cast.Cst_Cnt = Prodo_Cast.Cst_Cnt) INNER JOIN Weather ON Cast.Cst_Cnt = Weather.Cst_Cnt
WHERE (((Cast.Cruise)<=202105));

SELECT Bottle.*, Bottle_Q.*, Chl.*, Nuts.*, Prodo_Bottle.*, Rpt_Data.R_PRES, Rpt_Data.R_POTEMP, Rpt_Data.R_SVA, Rpt_Data.R_DYNHT, Rpt_Data.R_NH4, Rpt_Data.[R_Oxy_µmol/Kg], DICs.DIC1, DICs.DIC2, DICs.TA1, DICs.TA2, DICs.pH1, DICs.pH2, DICs.Btl_Cnt, DICs.[DIC Quality Comment] INTO Bottle_All_LTER_all
FROM Cast INNER JOIN ((((((Bottle LEFT JOIN DICs ON Bottle.Btl_Cnt = DICs.Btl_Cnt) INNER JOIN Bottle_Q ON Bottle.Btl_Cnt = Bottle_Q.Btl_Cnt) INNER JOIN Chl ON Bottle.Btl_Cnt = Chl.Btl_Cnt) INNER JOIN Nuts ON Bottle.Btl_Cnt = Nuts.Btl_Cnt) INNER JOIN Prodo_Bottle ON Bottle.Btl_Cnt = Prodo_Bottle.Btl_Cnt) INNER JOIN Rpt_Data ON Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((Cast.Cruise)<=202201));

SELECT Cast.Cruise, Bottle.Sta_ID, Bottle.Depthm, Bottle.T_degC, Bottle.Salnty, Bottle.O2ml_L, Chl.ChlorA, Chl.Phaeop, Nuts.PO4uM, Nuts.SiO3uM, Nuts.NO2uM, Nuts.NO3uM, Nuts.NH3uM, Bottle.Cst_Cnt, Bottle.Btl_Cnt, Bottle.STheta, Bottle.O2Sat, Bottle.[Oxy_µmol/Kg] INTO [Mati_Hydro_1902-2107_finalthru2001]
FROM Cast INNER JOIN ((Bottle INNER JOIN Chl ON Bottle.Btl_Cnt = Chl.Btl_Cnt) INNER JOIN Nuts ON Bottle.Btl_Cnt = Nuts.Btl_Cnt) ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((Cast.Cruise) Between 202204 And 202208) AND ((Bottle.RecInd)=3));

SELECT Cast.Cst_Cnt, Cast.Cruise_ID, Cast.Cruise, Cast.CruiseAlias, Cast.Cruz_Sta, Cast.DbSta_ID, Cast.Cast_ID, Cast.Sta_ID, Cast.Quarter, Cast.Sta_Code, Cast.Distance, Format([Cast].[Date],"mm/dd/yyyy") AS Date, Cast.Year, Cast.Month, Cast.Julian_Date, Cast.Julian_Day, Format([Cast].[Time],"hh:nn:ss") AS Time, Cast.Lat_Dec, Cast.Lat_Deg, Cast.Lat_Min, Cast.Lat_Hem, Cast.Lon_Dec, Cast.Lon_Deg, Cast.Lon_Min, Cast.Lon_Hem, Cast.Rpt_Line, Cast.St_Line, Cast.Ac_Line, Cast.Rpt_Sta, Cast.St_Station, Cast.Ac_Sta, Cast.Bottom_D, Cast.Secchi, Cast.ForelU, Cast.Ship_Name, Cast.Ship_Code, Cast.Data_Type, Cast.Order_Occ, Cast.Event_Num, Cast.Cruz_Leg, Cast.Orig_Sta_ID, Cast.Data_Or, Cast.Cruz_Num, Cast.IntChl, Cast.IntC14 INTO [Mati_Meta_201902-202101]
FROM Cast
WHERE (((Cast.Cruise) Between 202204 And 202208));

SELECT Cast.Cruise, Cast.Sta_ID, Bottle.Cst_Cnt, Bottle.Btl_Cnt, Bottle.Depthm, Cast.Order_Occ, NH4_Data.[NH4_uM/l] AS Expr1 INTO NH4_DB
FROM NH4_Data, Cast INNER JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((NH4_Data.Cruise)=[cast].[cruise]) AND ((NH4_Data.Order_Occ)=[Cast].[order_occ]) AND (([NH4_Data].[Btlnum])=[bottle].[btlnum]));

SELECT Cast.Cast_ID, Cast.Cruise, Cast.Sta_ID, Cast.Cst_Cnt, Prodo_Bottle.MeanAs, Prodo_Cast.IntC14, Cast.IntC14, Bottle.Depth_ID, Cast.Data_Type, Bottle.Btl_Cnt, Prodo_Cast.Civil_T, Cast.Cruise_ID
FROM (Prodo_Cast INNER JOIN Bottle ON Prodo_Cast.Cst_Cnt = Bottle.Cst_Cnt) INNER JOIN (Cast INNER JOIN Prodo_Bottle ON Cast.Cst_Cnt = Prodo_Bottle.Cst_Cnt) ON (Prodo_Cast.Cst_Cnt = Prodo_Bottle.Cst_Cnt) AND (Cast.Cst_Cnt = Prodo_Cast.Cst_Cnt) AND (Cast.Cst_Cnt = Bottle.Cst_Cnt) AND (Bottle.Btl_Cnt = Prodo_Bottle.Btl_Cnt)
WHERE (((Cast.Cst_Cnt)=23954));

SELECT *
FROM Bottle
WHERE (((Len([Depth_ID]))>38));

SELECT Bottle.Btl_Cnt, Bottle.Depth_ID, DICs.Btl_Cnt, DICs.Depth_ID, DICs.Cruise, Abs(Mid([Bottle]![Depth_ID],32,4)-Mid([DICs]![Depth_ID],32,4)) AS DepthID_Compare, [DICs]![StaPr]-Abs(Mid([Bottle].[Depth_ID],32,4)) AS [DIC_StaPr-Btl_DepthID_Depth], [DICs]![StaPr]-[Bottle]![Depthm] AS [DIC_StaPres-Btl_Depthm], [DICs]![Salinity1]-[Bottle]![Salnty] AS SalComp, DICs.Salinity1, Bottle.Salnty, DICs.TA1, DICs.Comments
FROM Bottle INNER JOIN DICs ON Bottle.Btl_Cnt = DICs.Btl_Cnt
WHERE (((DICs.Cruise)=201407));

SELECT DICs.Cruise, Abs([StaPr]-[Depthm]) AS depth_Comp, DICs.Depth_ID, DICs.Depthm, DICs.StaPr, DICs.Btl_Cnt
FROM DICs
WHERE (((DICs.Cruise)=201501));

SELECT Abs(Mid([Depth_ID],33,3)-([D_Depth1])) AS Depth_ID_Compare, [0808DIC_DB].Depth_ID AS Depth_ID, Abs([StaSalt]-[Salinity1]) AS sal_comp, [0808DIC_DB].StaSalt AS StaSalnty, [0808DIC_DB].Salinity1 AS DIC_Salnty, [0808DIC_DB].Ord_Occ, [0808DIC_DB].Bottle_ID, [0808DIC_DB].Bottle_ID2, [0808DIC_DB].Btl_Cnt, [0808DIC_DB].ID, [0808DIC_DB].StaSalt
FROM 0808DIC_DB
WHERE ((([0808DIC_DB].StaSalt) Is Not Null));

SELECT *
FROM Cast
WHERE (((Len([Cast_ID]))<30));

SELECT Cast.Cruise, Cast.Sta_ID, Weather.Wave_Dir, Weather.Wave_Ht, Weather.Wave_Prd, Weather.Wind_Dir, Weather.Wind_Spd, Weather.Barometer, Weather.Dry_T, Weather.Wet_T, Weather.Wea, Weather.Cloud_Typ, Weather.Cloud_Amt, Weather.Visibility, Weather.Secchi, Cast.Order_Occ
FROM Cast INNER JOIN Weather ON Cast.Cst_Cnt = Weather.Cst_Cnt
WHERE (((Cast.Cruise)=201207));

SELECT Cast.Year, Cast.Month, Cast.St_Line, Cast.St_Station, Bottle.Depthm, Bottle.T_degC, Bottle.Salnty, Bottle.O2ml_L, Bottle.BtlNum
FROM Cruises INNER JOIN (Cast INNER JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt) ON Cruises.Cruise = Cast.Cruise
WHERE (((Cast.St_Line)=86.7) AND ((Cast.St_Station)=40) AND ((Bottle.BtlNum)=1)) OR (((Cast.St_Line)=81.8) AND ((Cast.St_Station)=46.9) AND ((Bottle.BtlNum)=1));

SELECT Cast.Year, Cast.Month, Cast.Date, Cast.St_Line, Cast.St_Station, Bottle.Depthm, Bottle.T_degC, Bottle.Salnty, Bottle.[Oxy_µmol/Kg], Bottle.O2ml_L
FROM (Cruises INNER JOIN Cast ON Cruises.Cruise = Cast.Cruise) INNER JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((Cast.St_Station)=46.9) AND ((Bottle.Depthm)>560) AND ((Bottle.O2ml_L) Is Not Null));

SELECT Cruises.Cruise, Cruises.[Code-ST], Cruises.Ship1, Cruises.BegDate1, Cruises.EndDate1
FROM Cruises
WHERE (((Cruises.Cruise)>198400) AND ((Cruises.[Code-ST])="st"));

SELECT Cast.Cruise, Cast.Ship_Code, Cast.Sta_ID, Cast.Lon_Dec, Cast.Lat_Dec, Cast.Date
FROM Cast
WHERE (((Cast.Cruise)=198406));

SELECT Zooplankton.ID, Zooplankton.Cruise, Zooplankton.Sta_ID, Zooplankton.Cruz_Sta, Zooplankton.Order_Occ, Zooplankton.St_Line, Zooplankton.St_Sta, Avg([Zooplankton]![Lat_Deg]+([Zooplankton]![Lat_Min]/60)) AS Lat_Dec, Avg([Zooplankton]![Lon_Deg]+([Zooplankton]![Lon_Min]/60)) AS Lon_Dec, Zooplankton.Tow_Type, Zooplankton.Net_Loc, Zooplankton.Tow_Date, Zooplankton.Tow_Time, Avg([Zooplankton]![Tow_Date]+[Zooplankton]![Tow_Time]) AS Tow_DateTime, Zooplankton.Tow_DpthM, Zooplankton.Ttl_PVolC3, Zooplankton.Sml_PVolC3
FROM Zooplankton
GROUP BY Zooplankton.ID, Zooplankton.Cruise, Zooplankton.Sta_ID, Zooplankton.Cruz_Sta, Zooplankton.Order_Occ, Zooplankton.St_Line, Zooplankton.St_Sta, Zooplankton.Tow_Type, Zooplankton.Net_Loc, Zooplankton.Tow_Date, Zooplankton.Tow_Time, Zooplankton.Tow_DpthM, Zooplankton.Ttl_PVolC3, Zooplankton.Sml_PVolC3;

SELECT [TR - NMFS_Tows].NMFS_Sta_ID, Count([TR - NMFS_Tows].NMFS_OrdOcc) AS Times_Occup, Avg([TR - NMFS_Tows].NMFS_TowDateTimeGMT) AS NMFS_Time, Avg([TR - NMFS_Tows].NMFS_DLat) AS NMFS_DLat, Avg([TR - NMFS_Tows].NMFS_Dlong) AS NMFS_Dlong INTO [New-NMFS_Station_ID]
FROM [TR - NMFS_Tows]
GROUP BY [TR - NMFS_Tows].NMFS_Sta_ID;

SELECT Bottle.Cst_Cnt, Bottle.Sta_ID, Bottle.Depth_ID
FROM Cast INNER JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((Cast.Cst_Cnt) Is Null));

SELECT Cast.Cst_Cnt, Cast.Cruise, Cast.Sta_ID, Bottle.Cst_Cnt
FROM Cast LEFT JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt
WHERE (((Bottle.Cst_Cnt) Is Null));

SELECT Chl.Btl_Cnt, Chl.ChlorA, Bottle.Btl_Cnt
FROM Bottle RIGHT JOIN Chl ON Bottle.Btl_Cnt = Chl.Btl_Cnt
WHERE (((Bottle.Btl_Cnt) Is Null));

SELECT Nuts.Btl_Cnt, Nuts.PO4ug AS Expr1, Bottle.Btl_Cnt
FROM Nuts LEFT JOIN Bottle ON Nuts.Btl_Cnt = Bottle.Btl_Cnt
WHERE (((Bottle.Btl_Cnt) Is Null));

SELECT Prodo_Bottle.Cst_Cnt AS Expr1, Prodo_Bottle.Btl_Cnt
FROM Prodo_Bottle, Prodo_Cast
WHERE (((Prodo_Cast.Cst_Cnt) Is Null));

SELECT Prodo_Cast.Cst_Cnt, Prodo_Cast.Cast_ID AS Expr1
FROM Cast RIGHT JOIN Prodo_Cast ON Cast.Cst_Cnt = Prodo_Cast.Cst_Cnt
WHERE (((Cast.Cst_Cnt)=[prodo_cast].[cst_cnt]) AND ((Cast.Cast_ID)<>[Prodo_Cast].[Cast_ID]));

SELECT Cast.Cruise, Cast.Sta_ID, Cast.Date, Prodo_Cast.Cst_Cnt
FROM Cast INNER JOIN (Prodo_Bottle RIGHT JOIN Prodo_Cast ON Prodo_Bottle.Cst_Cnt = Prodo_Cast.Cst_Cnt) ON Cast.Cst_Cnt = Prodo_Cast.Cst_Cnt
WHERE (((Prodo_Bottle.Cst_Cnt) Is Null));

SELECT Station_ID.ID, Station_ID.Sta_ID, Station_ID.DBSta_ID, Station_ID.Sta_Code
FROM Station_ID LEFT JOIN Cast ON Station_ID.DBSta_ID = Cast.DbSta_ID
WHERE (((Cast.DbSta_ID) Is Null));

SELECT Cast.Cst_Cnt, Cast.Cruise, Cruises.Ship1, Cast.Sta_ID, Station_ID.Sta_Code
FROM Cruises INNER JOIN (Station_ID INNER JOIN Cast ON Station_ID.Sta_ID = Cast.Sta_ID) ON Cruises.Cruise = Cast.Cruise
WHERE (((Cast.Cruise)=199702));

UPDATE Cast INNER JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt
SET Bottle.Depth_ID = Left([Depth_ID],7)+Right([Ship_Code],2)+Right([Depth_ID],29)
WHERE (((InStr([Bottle].[Depth_ID],Right([Cast].[Ship_Code],2)))="0"));

UPDATE Cast INNER JOIN Bottle ON Cast.Cst_Cnt = Bottle.Cst_Cnt
SET Bottle.[Oxy_µmol/Kg] = (([Bottle].[O2ml_L]*44660)/([Bottle].[STheta]+1000))
WHERE (((Cast.Cruise)=201604) AND ((Bottle.O2ml_L) Is Not Null));

UPDATE Bottle1 INNER JOIN [1995-2009Bottle] ON Bottle1.Btl_Cnt=[1995-2009Bottle].Btl_Cnt
SET Bottle1.BtlNum = [1995-2009Bottle].BtlNum
WHERE (((Bottle1.Depthm)=[1995-2009Bottle].Depthm) And ((Bottle1.Btl_Cnt)=[1995-2009Bottle].Btl_Cnt));

UPDATE Cast
SET Cast.Cast_ID = Left([Cast_ID],7)+Right([Ship_Code],2)+Right([Cast_ID],21)
WHERE (((InStr([Cast_ID],Right([Ship_Code],2)))="0"));

UPDATE Cast
SET Cast.CruiseAlias = [cast].[Cruise]
WHERE (((Cast.Cruise)=202304));

UPDATE Zooplankton
SET Zooplankton.CruiseAlias = [Zooplankton].[Cruise]
WHERE (((Zooplankton.Cruise)=201802));

UPDATE Cast, Cast1
SET Cast.Ship_Code = Cast1.Ship_Code
WHERE (((Cast.Ship_Code)<>[Cast1].[Ship_Code]));

UPDATE Bottle
SET Bottle.Depth_ID = Replace([Depth_ID],"-PR-","-MX-")
WHERE (((Bottle.Depth_ID) Like "*-8410NM-PR-*") AND ((Bottle.Cst_Cnt)=23954));

UPDATE Cast INNER JOIN Prodo_Cast ON Cast.Cst_Cnt = Prodo_Cast.Cst_Cnt
SET Prodo_Cast.Cast_ID = Left(Prodo_Cast.Cast_ID,7)+Right(Cast.Ship_Code,2)+Right(Prodo_Cast.Cast_ID,21)
WHERE (((InStr([Prodo_Cast].[Cast_ID],Right([Cast].[Ship_Code],2)))="0"));

UPDATE Prodo_Cast INNER JOIN Prodo_Bottle ON Prodo_Cast.Cst_Cnt = Prodo_Bottle.Cst_Cnt
SET Prodo_Bottle.IncTim = Format(Abs([Prodo_Cast].[Inc_Str]-[Prodo_Cast].[Inc_End]),"Long Time")
WHERE (((Prodo_Bottle.C14As1) Is Not Null) AND ((Prodo_Bottle.C14As2) Is Not Null) AND ((Prodo_Bottle.DarkAs) Is Not Null) AND ((Prodo_Bottle.Btl_Cnt)>=887236));

UPDATE Cast
SET Cast.Rpt_Line = Format(Val(Left(Cast.Sta_ID,5)),"#.0"), Cast.Rpt_Sta = Format(Val(Right(Cast.Sta_ID,5)),"#.0")
WHERE (((Cast.Year)>2008));

UPDATE Rpt_Data
SET Rpt_Data.[R_Oxy_µmol/Kg] = (([Rpt_Data].[R_O2]*44660)/([Rpt_Data].[R_SIGMA]+1000))
WHERE (((Rpt_Data.R_O2) Is Not Null) AND ((Rpt_Data.Btl_Cnt)>862871));

UPDATE Cast INNER JOIN (Bottle INNER JOIN Rpt_Data ON Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) ON Cast.Cst_Cnt = Bottle.Cst_Cnt
SET Rpt_Data.[R_Oxy_µmol/Kg] = [Bottle].[Oxy_µmol/Kg]
WHERE (((Cast.Cruise)=202304));

UPDATE Cast INNER JOIN [0-Ships] ON Cast.Ship_Code = [0-Ships].Ship_Code
SET Cast.Ship_Name = [0-Ships].Ship_Name
WHERE (((Cast.Ship_Name)<>[0-Ships].[Ship_Name]) AND ((Cast.Ship_Code)=[0-Ships].[Ship_Code]));

INSERT INTO DICs (ID, Cruise, Btl_Cnt, StaPr, Depthm, Depth_ID, Sta_ID, pH1, pH2, DIC1, DIC2, TA1, TA2, Salinity1, Salinity2, Bottle_ID2, Niskin)
SELECT [1507DIC_DB].ID, [1507DIC_DB].Cruise, [1507DIC_DB].Btl_Cnt, [1507DIC_DB].StaPr, [1507DIC_DB].Depthm, [1507DIC_DB].Depth_ID, [1507DIC_DB].Sta_ID, [1507DIC_DB].pH1, [1507DIC_DB].pH2, [1507DIC_DB].DIC1, [1507DIC_DB].DIC2, [1507DIC_DB].TA1, [1507DIC_DB].TA2, [1507DIC_DB].Salinity1, [1507DIC_DB].Salinity2, [1507DIC_DB].Bottle_ID2, [1507DIC_DB].D_Nisk1
FROM 1507DIC_DB;

UPDATE Bottle
SET Bottle.Depth_ID = Replace([Depth_ID],"-800505","-08000505")
WHERE (((Bottle.Depth_ID) Like "*-800505*") AND ((Bottle.Cst_Cnt)>32423));

UPDATE Bottle
SET Bottle.Depth_ID = Replace([Depth_ID],"0470","0469")
WHERE (((Bottle.Depth_ID) Like "*-08180470*") AND ((Bottle.Cst_Cnt)>32423));

UPDATE Cast
SET Cast.St_Station = Replace([St_Station],"47","46.9")
WHERE (((Cast.St_Station) Like "*47") AND ((Cast.Year)>2008));

UPDATE Bottle
SET Bottle.Sta_ID = Replace([Sta_ID],"86.7 050.0","086.7 050.0")
WHERE (((Bottle.Sta_ID) Like "86.7 050.0") AND ((Bottle.Cst_Cnt)>32665));

UPDATE Cast INNER JOIN (Bottle INNER JOIN DICs ON Bottle.Sta_ID = DICs.Sta_ID) ON (Cast.Cst_Cnt = Bottle.Cst_Cnt) AND (Cast.Cruise = DICs.Cruise)
SET DICs.Depth_ID = [Bottle].[Depth_ID], DICs.Btl_Cnt = [Bottle].[Btl_Cnt]
WHERE (((Cast.Cruise)=201402) AND ((Cast.Cst_Cnt)<>33468) AND ((DICs.Niskin)=[Bottle].[BtlNum]) AND ((DICs.Sta_ID)=[Bottle].[Sta_ID]));

UPDATE (1507DIC_DB INNER JOIN Cast ON [1507DIC_DB].Cruise = Cast.Cruise) INNER JOIN Bottle ON (Cast.Cst_Cnt = Bottle.Cst_Cnt) AND ([1507DIC_DB].Sta_ID = Bottle.Sta_ID)
SET [1507DIC_DB].Depth_ID = [Bottle].[Depth_ID], [1507DIC_DB].Btl_Cnt = [Bottle].[Btl_Cnt]
WHERE ((([1507DIC_DB].StaNisk)=[Bottle].[BtlNum]) AND ((Cast.Cruise)=201507) AND (([1507DIC_DB].Sta_ID)=[Bottle].[Sta_ID]));

UPDATE Cast
SET Cast.Rpt_Line = Format(Val(Right([Rpt_Line],4)),"#.0")
WHERE (((Cast.Rpt_Line) Like "90" Or (Cast.Rpt_Line)="80" Or (Cast.Rpt_Line)="70" Or (Cast.Rpt_Line)="60") AND ((Cast.Cst_Cnt)>=35959));

UPDATE Cast
SET Cast.Rpt_Sta = Format(Val(Right([Rpt_Sta],4)),"#.0")
WHERE (((Cast.Rpt_Sta) Like "28" Or (Cast.Rpt_Sta)="30" Or (Cast.Rpt_Sta)="35" Or (Cast.Rpt_Sta)="37" Or (Cast.Rpt_Sta)="45" Or (Cast.Rpt_Sta)="50" Or (Cast.Rpt_Sta)="53" Or (Cast.Rpt_Sta)="60" Or (Cast.Rpt_Sta)="55" Or (Cast.Rpt_Sta)="70" Or (Cast.Rpt_Sta)="80" Or (Cast.Rpt_Sta)="90" Or (Cast.Rpt_Sta)="42" Or (Cast.Rpt_Sta)="51" Or (Cast.Rpt_Sta)="33" Or (Cast.Rpt_Sta)="40" Or (Cast.Rpt_Sta)="49") AND ((Cast.Cst_Cnt)>=35128));

UPDATE Cast
SET Cast.Rpt_Sta = Format(Val(Right([Rpt_Sta],5)),"#.0")
WHERE (((Cast.Rpt_Sta) Like "100" Or (Cast.Rpt_Sta)="110" Or (Cast.Rpt_Sta)="120") AND ((Cast.Cst_Cnt)>=35128));

UPDATE [0-Ships] INNER JOIN Cast ON [0-Ships].Ship_Code = Cast.Ship_Code
SET Cast.Ship_Name = [0-Ships].Ship_Name
WHERE (((Cast.Ship_Name)<>[0-Ships].[Ship_Name]));

SELECT Zooplankton.Cruise, Zooplankton.Sta_ID, Zooplankton.Cruz_Sta, Zooplankton.Ship_Code, Zooplankton.Order_Occ, Zooplankton.St_Line, Zooplankton.St_Station, Zooplankton.Lat_Deg, Zooplankton.Lat_Min, Zooplankton.Lat_Hem, Zooplankton.Lon_Deg, Zooplankton.Lon_Min, Zooplankton.Lon_Hem, Zooplankton.Tow_Type, Zooplankton.Net_Loc, Zooplankton.Tow_Date, Zooplankton.Tow_Time, Zooplankton.End_Time, Zooplankton.Vol_StrM3, Zooplankton.Tow_DpthM, Zooplankton.Ttl_PVolC3, Zooplankton.Sml_PVolC3, Zooplankton.HaulFact
FROM Zooplankton
WHERE (((Zooplankton.Cruise)=201704) AND ((Zooplankton.Net_Loc)="S"));
